"""Only generated bytes, never commercial ROMs."""

import subprocess
from hashlib import sha256
from struct import pack

import pytest

from recarted.convert import convert_image
from recarted.example import example_image
from recarted.images import KNOWN_ROMS, identify


@pytest.mark.parametrize(("mapper", "size"), [(1, 8192), (2, 16384)])
def test_header_and_payload(mapper, size, monkeypatch):
    raw = bytes(range(256)) * (size // 256)
    image = identify(raw, suffix=".ROM")
    assert image.medium == "ROM" and image.mapper is None
    with pytest.raises(ValueError, match=f"--rom-type {mapper}"):
        convert_image(image)
    result = convert_image(image, rom_type=mapper)
    assert result == pack(">4sIII", b"CART", mapper, sum(raw), 0) + raw
    assert identify(result).mapper == mapper
    with pytest.raises(ValueError, match="requires"):
        convert_image(image, rom_type=3 - mapper)
    monkeypatch.setitem(KNOWN_ROMS, sha256(raw).hexdigest(), ("demo", mapper))
    assert convert_image(identify(raw, suffix=".rom")) == result


def test_rom_fallback_preserves_magic_and_refuses_unsupported():
    assert identify(example_image("cas"), suffix=".rom").medium == "CAS"
    with pytest.raises(ValueError, match="recognized header"):
        convert_image(identify(example_image("atr"), suffix=".rom"), rom_type=1)
    with pytest.raises(ValueError, match="Bad CAR checksum"):
        identify(pack(">4sIII", b"CART", 1, 1, 0) + bytes(8192), suffix=".rom")
    with pytest.raises(ValueError, match="Unrecognized file signature"):
        identify(bytes(8192), suffix=".img")
    image = identify(bytes(32768), suffix=".rom")
    with pytest.raises(ValueError, match="use a CAR with the correct mapper"):
        convert_image(image)
    with pytest.raises(ValueError, match="supports only"):
        convert_image(image, rom_type=12)
    with pytest.raises(ValueError, match="not converted to .xex"):
        convert_image(image, "xex")


def test_cli_rom(tmp_path):
    def cli(*args):
        return subprocess.run(
            ["recarted", *args],
            capture_output=True,
            text=True,
            cwd=tmp_path,
            check=False,
        )

    raw = tmp_path / "unknown.ROM"
    raw.write_bytes(bytes(8192))
    probe = cli("inspect", raw.name)
    assert probe.returncode == 0 and "--rom-type 1" in probe.stdout
    out = raw.with_suffix(".car")
    deny = cli("convert", raw.name)
    assert deny.returncode and "Unknown mapping" in deny.stderr and not out.exists()
    assert cli("convert", raw.name, "--rom-type", "1").returncode == 0
    assert (
        out.read_bytes()[16:] == raw.read_bytes()
        and "Type 1;" in cli("inspect", out.name).stdout
    )
    assert cli("convert", raw.name, "--rom-type", "1").returncode != 0
